pending_requests = {}

def send_request(method, params):
    request_id = next_id()
    pending_requests[request_id] = create_pending_future()
    transport.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
    return pending_requests[request_id]

def on_message(message):
    if "id" in message and message["id"] in pending_requests:
        future = pending_requests.pop(message["id"])
        future.resolve(message)

class IdGenerator:
    def __init__(self):
        self._next = 1

    def next_id(self):
        current = self._next
        self._next += 1
        return current

def send_request_with_timeout(method, params, timeout_seconds=30):
    future = send_request(method, params)
    if not future.wait(timeout_seconds):
        pending_requests.pop(future.id, None)
        return timeout_error(method)
    return future.result

def on_transport_closed(pending_requests, reason):
    for request_id, future in list(pending_requests.items()):
        future.reject(connection_closed_error(reason))
        pending_requests.pop(request_id, None)
